import{z as D,x as o,o as e,c as n,q as t,j as r,D as a,d as A,s as l,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"KEM 与混合加密","description":"","frontmatter":{"title":"KEM 与混合加密","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-kem-hybrid.md","filePath":"cs/ce-kem-hybrid.md","lastUpdated":1791413859000}'),d={name:"cs/ce-kem-hybrid.md"};function p(C,E,F,K,c,M){const B=o("Mermaid");return e(),n("div",null,[E[2]||(E[2]=t('<h1 id="kem-与混合加密" tabindex="-1">KEM 与混合加密 <a class="header-anchor" href="#kem-与混合加密" aria-label="Permalink to &quot;KEM 与混合加密&quot;">​</a></h1><div class="epigraph"><p>公钥加密的正确形状不是「拿对方公钥加密消息」，而是「封装一把会话密钥，再用 AEAD 履行合同」——KEM/DEM 把这句话写成了接口。</p><footer>—— 据 Shoup, 2001；RFC 9180；FIPS 203 整理</footer></div><p><a href="/cs/ce-signature-practice">上一课</a>把签名纪律钉在 nonce 与验证器上。现在看保密方向：<a href="/cs/ecdh-x25519">ECDH 与 X25519</a>给了协商原语，<a href="/cs/rsa-attacks">RSA 攻击面</a>解释了为什么 RSA 直接加密消息的形状退出历史。缺口是<strong>接口</strong>：现代协议（TLS 1.3、HPKE、后量子迁移）都不再「用公钥加密数据」，而是 KEM 封装对称密钥、DEM 做 AEAD。本课钉这个接口的合同、它在格密码上的版本、以及混合迁移的做法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书公钥加密把消息直接喂进陷门函数，工程上从来不能这么用：明文要结构化、长度受限、且没有 CCA 安全。KEM 的解法是把「加密任意消息」换成「加密一把定长密钥」：encapsulate(pk) 输出 \\((ct, ss)\\)，decapsulate(sk, ct) 还原 \\(ss\\)，\\(ss\\) 经 KDF 进 AEAD——后半叫 DEM，就是<a href="/cs/ce-aead-deep">AEAD 的深入</a>那套合同。组合「KEM+DEM = 公钥加密」要满足的是 CCA 安全：对手能拿任意密文去问解密预言，仍不能区分挑战密文。缺口是三问：KEM 从哪来（DH 怎么变成 KEM、格加密怎么变成 KEM）、发送方身份谁认证、迁移怎么走。</p><p><span class="marginnote">直觉类比：KEM/DEM 像寄保险箱——先用对方的公钥「封装」出一把一次性小钥匙（KEM，只搬钥匙不搬货），再用这把钥匙锁住真正的货箱（DEM，普通对称加密）；公钥数学慢而贵，只干一次搬钥匙的活。</span></p><p><span class="marginnote">常见误区：初学者容易以为「拿对方公钥把消息整个加密」就是标准做法，实际上明文长度受限、没有 CCA 安全——RSA 直接加密消息的形状正是因为这些退出历史，现代协议只让公钥原语搬运密钥。</span></p><h3 id="dh-kem-与-fo-变换" tabindex="-1">DH-KEM 与 FO 变换 <a class="header-anchor" href="#dh-kem-与-fo-变换" aria-label="Permalink to &quot;DH-KEM 与 FO 变换&quot;">​</a></h3><p>X25519 本身就是一个 KEM 雏形：发送方临时密钥对 \\((a, aG)\\)，封装密文 \\(ct = aG\\)，共享秘密取 \\(\\mathrm{HKDF}(a \\cdot B)\\)，\\(B\\) 是接收方公钥。裸构造不带密钥确认，CCA 证明落在 GDH 一类较强假设上；HPKE（RFC 9180）把两把公钥卷进 HKDF 的套件标识做域分离，给出标准化构造。格侧不同：ML-KEM（FIPS 203，原 Kyber）的底层加密只有 CPA 安全，Fujisaki–Okamoto 变换把解密端改成「重新加密并比对」——解密结果与密文不一致即拒绝，CPA 加密由此升到 CCA 的 KEM。</p><p><span class="marginnote">术语翻译：FO 变换就是用「解密前先重新加密一遍并比对」的手段来做「把 CPA 加密升到 CCA」的事——对手若篡改密文来试探解密预言，比对不一致直接拒绝，试探的嘴被堵上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程口径四条。其一，消息保密一律 KEM+DEM：KEM 出共享秘密，HKDF 派生，AEAD 加密；绝不把公钥原语的输出直接当密文用。其二，认证归属：KEM 只对「谁能解开」负责，不证明发送者；要认证就叠加签名（上一课的合同）或预共享钥，TLS 1.3 的证书正是叠在临时 DH 之上。其三，前向保密来自临时性：KEM 密钥对每会话即弃；静态公钥解密的服务（给多个接收者发件）没有前向保密，长存私钥泄露会回溯解开历史密文。其四，后量子迁移用混合：X25519 与 ML-KEM-768 各封装一次，两个共享秘密拼接过 KDF——任何一边被破，另一边还撑着；TLS 的 X25519MLKEM768 组合已按此部署。</p>',12)),(e(),r(i,null,{default:a(()=>[l(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEND%5B%22%E5%8F%91%E9%80%81%E6%96%B9%22%5D%20--%3E%20ENC%5B%22encapsulate(pk)%22%5D%0A%20%20ENC%20--%3E%20CT%5B%22ct%20%E4%B8%8E%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%20ss%22%5D%0A%20%20CT%20--%3E%20KDF%5B%22HKDF%20%E5%9F%9F%E5%88%86%E7%A6%BB%E6%B4%BE%E7%94%9F%22%5D%0A%20%20KDF%20--%3E%20AEAD%5B%22AEAD%20%E5%8A%A0%E5%AF%86%E6%B6%88%E6%81%AF%EF%BC%88DEM%EF%BC%89%22%5D%0A%20%20AEAD%20--%3E%20WIRE%5B%22ct%20%2B%20%E5%AF%86%E6%96%87%20%2B%20tag%20%E4%B8%8A%E9%93%BE%E8%B7%AF%22%5D%0A%20%20RECV%5B%22%E6%8E%A5%E6%94%B6%E6%96%B9%22%5D%20--%3E%20DEC%5B%22decapsulate(sk%2C%20ct)%20%E8%BF%98%E5%8E%9F%20ss%22%5D%0A%20%20DEC%20--%3E%20KDF%0A%20%20SEND%20--%3E%20AUTH%7B%22%E8%A6%81%E8%AE%A4%E8%AF%81%E5%8F%91%E9%80%81%E8%80%85%3F%22%7D%0A%20%20AUTH%20--%3E%7C%E6%98%AF%7C%20SIG%5B%22%E5%8F%A0%E5%8A%A0%E7%AD%BE%E5%90%8D%EF%BC%88%E4%B8%8A%E4%B8%80%E8%AF%BE%E5%90%88%E5%90%8C%EF%BC%89%22%5D%0A%20%20SIG%20--%3E%20WIRE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=s("h2",{id:"机制",tabindex:"-1"},[A("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=s("p",null,"KEM 为什么是「更小的合同」？它把「任意长度、结构化明文」的编码问题从公钥原语里拿掉，塞给对称侧：封装输出永远是定长密钥与定长密文，剩下的一切交给 AEAD 与消息格式。CCA 安全在 DEM 侧由 AEAD 自带的认证给出——篡改密文则标签失败；在 KEM 侧由构造给出——FO 变换把解密预言的每一问都变成自检。两半的合同叠起来，才抵得上「CCA 安全公钥加密」这个旧目标。混合迁移同理是把风险对冲写进协议：拼接两个共享秘密后，安全性取两侧较弱者——除非两边同时被破，防线不塌；它防的是「单一方案被整体击穿」，不是「双倍强度」。",-1)),(e(),r(i,null,{default:a(()=>[l(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E6%B6%88%E6%81%AF%22%5D%20--%3E%20X%5B%22X25519%20%E5%B0%81%E8%A3%85%EF%BC%9A%E7%BB%8F%E5%85%B8%E6%A4%AD%E5%9C%86%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20M%20--%3E%20K%5B%22ML-KEM-768%20%E5%B0%81%E8%A3%85%EF%BC%9A%E6%A0%BC%22%5D%0A%20%20X%20--%3E%20SX%5B%22%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%20ss1%22%5D%0A%20%20K%20--%3E%20SK%5B%22%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%20ss2%22%5D%0A%20%20SX%20--%3E%20CAT%5B%22%E4%B8%A4%E4%B8%AA%20ss%20%E6%8B%BC%E6%8E%A5%E5%90%8E%E8%BF%87%E4%B8%80%E6%AC%A1%20KDF%22%5D%0A%20%20SK%20--%3E%20CAT%0A%20%20CAT%20--%3E%20KEY%5B%22%E5%94%AF%E4%B8%80%E4%B8%80%E6%8A%8A%E4%BC%9A%E8%AF%9D%E5%AF%86%E9%92%A5%22%5D%0A%20%20BREAK%5B%22%E4%BB%BB%E4%B8%80%E8%BE%B9%E8%A2%AB%E6%95%B4%E4%BD%93%E5%87%BB%E7%A9%BF%22%5D%20-.-%3E%7C%22%E5%8F%A6%E4%B8%80%E8%BE%B9%E7%9A%84%E7%86%B5%E4%BB%8D%E4%BF%9D%E5%AF%86%22%7C%20KEY%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">数字实例：X25519 封装出 32 字节的 ss；ML-KEM-768 封装出 32 字节 ss 加 1088 字节密文。两者拼成 64 字节再过 HKDF——不是 128 位变 256 位，而是「经典算法被量子计算机整体击穿时，格那半边还在」。</span></p><p><span class="marginnote">尺寸账：X25519 公钥 32 字节；ML-KEM-768 公钥 1184 字节、密文 1088 字节。TLS 握手里每个方向多出约 2 KB——这是迁移的物理成本，也是「不到期限不提前全量混合」的工程理由。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只钉 KEM/DEM 接口与混合口径；证书怎么把公钥绑到名字、握手怎么协商套件，属于 <a href="/cs/tls-handshake">TLS 握手</a>与 PKI 层。群上签名的纪律在上一课；PIR、MPC 这类「对加密数据直接计算」的路线（见 <a href="/cs/pir">PIR</a>）与 KEM 不在同一条线上，不要混装。后量子对签名的冲击（ML-DSA、SLH-DSA 与尺寸暴涨）是下一课的主题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公钥加密的正确接口是 KEM+DEM：封装会话密钥，AEAD 履行消息合同。</li><li>DH-KEM 把 X25519 的共享点过 HKDF；格侧靠 FO 变换从 CPA 升到 CCA。</li><li>KEM 不认证发送者；认证叠加签名或 PSK，前向保密来自密钥临时性。</li><li>后量子迁移用混合封装：拼接共享秘密，安全性取较弱侧。</li><li>出处：Shoup, 2001；RFC 9180；FIPS 203（ML-KEM）；RFC 8446。</li></ul>',6))])}const S=D(d,[["render",p]]);export{m as __pageData,S as default};
